package testutil

// GTSRootR1B64 and GTSRootR4B64 are the Google Trust Services roots that the
// chains of cgr.dev and of the storage host it redirects blob reads to verify
// to, as standard padded base64 DER: the anchors a lane declares for that
// registry and its storage. SSLComRootECCB64 is the root the public DoT
// resolver one.one.one.one verifies to. They are public roots, not test key
// material, and the same text the bootstrap lane template carries.
const (
	GTSRootR1B64     = ""
	GTSRootR4B64     = ""
	SSLComRootECCB64 = ""
)
